-- LF M4, 112 fuentes inventariadas, 8 candidatas; ninguna regla publicada ni deprecada.
-- Fuente fichas: sandbox/lf_contract_gate_test/nucleo_ci/m4b_8_candidatas_v1.json
BEGIN;
DO $m4$
DECLARE f jsonb; p jsonb; dry jsonb; applied jsonb; eval jsonb; t jsonb; truth jsonb; bad jsonb; mutant_truth jsonb;
 code text; ref_id integer; n integer:=0; cases integer; total_tests integer:=0; actual_sources integer;
 oldlegacy jsonb; oldrules jsonb; oldversions jsonb; olddeprec jsonb; oldapps jsonb; oldeffective jsonb; oldekb integer;
BEGIN
 SELECT count(*) INTO actual_sources FROM lf_ops.nucleo_regla_familia f
 JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia IN ('SECURITY','MFA_OTP_SSO','SESSION','RATE_LIMIT');
 IF actual_sources<>112 OR EXISTS (SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo LIKE 'M4-B0%') THEN RAISE EXCEPTION 'M4B_SOURCE_OR_ID_DRIFT %',actual_sources; END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO oldlegacy FROM lf_ops.reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) INTO oldrules FROM lf_ops.nucleo_reglas r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO oldversions FROM lf_ops.nucleo_regla_versiones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) INTO olddeprec FROM lf_ops.nucleo_deprecaciones r;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) INTO oldapps FROM lf_ops.nucleo_aplicaciones r;
 SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla)
 INTO oldeffective FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e;
 SELECT count(*) INTO oldekb FROM public.lf_error_knowledge;
 FOR f IN SELECT value FROM jsonb_array_elements('[{"codigo":"m4b_intento_reanudar_otp_pendiente","familia":"SESSION","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_otp_pendiente_sesion_expirada","familia":"SESSION","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_retomar_onboarding","familia":"SESSION","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_sesion_expirada_con_precarga","familia":"SESSION","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_mutacion_sesion","familia":"SESSION","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_onboarding_completado","familia":"SESSION","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_reenvio_backend","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_cooldown_backend_otp_activo","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_habilitar_reenvio_ui","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_timer_otp_ordinario_no_vencido","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_reenvio_tras_agotamiento","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_cooldown_agotamiento_reenvios_activo","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_cambiar_numero_inline","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_limite_cambio_inline_excedido","familia":"RATE_LIMIT","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_intento_captcha_paso_otp","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"},{"codigo":"m4b_captcha_adicional_otp_presentado","familia":"SECURITY","tipo_dato":"boolean","unidad":"ninguna","tabla_ref":null,"columna_ref":null,"binding":"Paulo pendiente"}]'::jsonb) LOOP
  code:=f->>'codigo';
  IF EXISTS (SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo=code) THEN RAISE EXCEPTION 'M4B_FACT_COLLISION %',code; END IF;
  INSERT INTO lf_ops.nucleo_hechos(codigo,tipo_dato,unidad,descripcion) VALUES (code,'boolean','ninguna','Hecho lógico M4 seguridad, fuente backend/cliente y binding Paulo pendientes; tabla_ref y columna_ref NULL');
  INSERT INTO lf_ops.nucleo_familia_vocabulario(familia,hecho,origen) VALUES(f->>'familia',code,'CURADO');
 END LOOP;
 FOR p IN SELECT value FROM jsonb_array_elements('[{"tipo":"NUEVA","codigo":"M4-B01","clave":"m4b_14","titulo":"Expiración de sesión OTP no completada","descripcion":"En intento de reanudar sesión incompleta sin OTP verificado, BLOQUEAR si venció la ventana AUTH/ONBOARDING_UNVERIFIED_SESSION_EXPIRATION_MINUTES de public.lf_global_config; exigir ABANDONED. No bloquear nueva sesión ni sesión verificada. El cálculo y persistencia se acreditan con Paulo.","familia":"SESSION","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_reanudar_otp_pendiente"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_otp_pendiente_sesion_expirada"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/14","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_reanudar_otp_pendiente":true,"m4b_otp_pendiente_sesion_expirada":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reanudar_otp_pendiente":true,"m4b_otp_pendiente_sesion_expirada":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reanudar_otp_pendiente":false,"m4b_otp_pendiente_sesion_expirada":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reanudar_otp_pendiente":false,"m4b_otp_pendiente_sesion_expirada":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B02","clave":"m4b_15","titulo":"Sesión expirada no recupera datos del intento previo","descripcion":"Al intentar recuperar una sesión expirada, BLOQUEAR continuar o precargar datos y exigir inicio desde Paso 1. No afecta sesión todavía activa ni flujos de nueva autenticación.","familia":"SESSION","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_retomar_onboarding"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_sesion_expirada_con_precarga"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/15","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_retomar_onboarding":true,"m4b_sesion_expirada_con_precarga":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_retomar_onboarding":true,"m4b_sesion_expirada_con_precarga":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_retomar_onboarding":false,"m4b_sesion_expirada_con_precarga":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_retomar_onboarding":false,"m4b_sesion_expirada_con_precarga":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B03","clave":"m4b_18","titulo":"No mutar la sesión de onboarding completada","descripcion":"Cuando se intenta modificar la misma sesión de onboarding ya finalizada, BLOQUEAR la modificación; posteriores cambios usan un flujo autenticado separado de Mi Cuenta. No bloquear lectura autorizada.","familia":"SESSION","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_mutacion_sesion"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_onboarding_completado"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/18","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_mutacion_sesion":true,"m4b_onboarding_completado":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_mutacion_sesion":true,"m4b_onboarding_completado":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_mutacion_sesion":false,"m4b_onboarding_completado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_mutacion_sesion":false,"m4b_onboarding_completado":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B04","clave":"m4b_30","titulo":"Respeto del cooldown de seguridad de reenvío OTP","descripcion":"Solo ante un intento efectivo de reenvío OTP, BLOQUEAR si continúa el cooldown ordinario de AUTH/OTP_ORDINARY_RESEND_TIMER_SECONDS o prevalece cooldown de agotamiento AUTH/OTP_EXHAUSTION_COOLDOWN_SECONDS tras AUTH/OTP_MAX_ATTEMPTS. Parámetros gobernados por public.lf_global_config y lector public.lf_auth_config_integer_v1. Sin números fijos ni decisión de umbral nueva.","familia":"RATE_LIMIT","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_reenvio_backend"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_cooldown_backend_otp_activo"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/30","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_reenvio_backend":true,"m4b_cooldown_backend_otp_activo":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reenvio_backend":true,"m4b_cooldown_backend_otp_activo":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reenvio_backend":false,"m4b_cooldown_backend_otp_activo":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reenvio_backend":false,"m4b_cooldown_backend_otp_activo":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B05","clave":"m4b_63","titulo":"Deshabilitar reenvío UI durante timer ordinario","descripcion":"En pantalla OTP, al intentar habilitar reenvío visual, BLOQUEAR mientras no venza timer AUTH/OTP_ORDINARY_RESEND_TIMER_SECONDS obtenido de public.lf_global_config según tiempo server-side. No sustituye el bloqueo de backend.","familia":"RATE_LIMIT","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_habilitar_reenvio_ui"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_timer_otp_ordinario_no_vencido"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/63","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_habilitar_reenvio_ui":true,"m4b_timer_otp_ordinario_no_vencido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_habilitar_reenvio_ui":true,"m4b_timer_otp_ordinario_no_vencido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_habilitar_reenvio_ui":false,"m4b_timer_otp_ordinario_no_vencido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_habilitar_reenvio_ui":false,"m4b_timer_otp_ordinario_no_vencido":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B06","clave":"m4b_64","titulo":"Cooldown temporal por agotamiento de reenvíos","descripcion":"Al solicitar reenvío OTP después de agotar el máximo AUTH/OTP_MAX_RESENDS, BLOQUEAR mientras siga el cooldown AUTH/OTP_RESEND_LIMIT_COOLDOWN_MINUTES de public.lf_global_config leído mediante public.lf_auth_config_integer_v1. No bloquear permanentemente ni otras sesiones.","familia":"RATE_LIMIT","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"BACKEND","modo":"HEREDA","clase":"BACKEND","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_reenvio_tras_agotamiento"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_cooldown_agotamiento_reenvios_activo"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/64","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_reenvio_tras_agotamiento":true,"m4b_cooldown_agotamiento_reenvios_activo":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reenvio_tras_agotamiento":true,"m4b_cooldown_agotamiento_reenvios_activo":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reenvio_tras_agotamiento":false,"m4b_cooldown_agotamiento_reenvios_activo":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_reenvio_tras_agotamiento":false,"m4b_cooldown_agotamiento_reenvios_activo":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B07","clave":"m4b_65","titulo":"Rate de cambios de celular inline por sesión","descripcion":"Solo al intentar cambiar inline el número de una sesión, BLOQUEAR exceso del máximo AUTH/PHONE_UPDATE_MAX_PER_SESSION de public.lf_global_config, con mensaje de soporte. No aplicar a otras sesiones ni confundir con bloqueo de campo y nueva sesión REG_SEG_005.","familia":"RATE_LIMIT","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_cambiar_numero_inline"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_limite_cambio_inline_excedido"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/65","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_cambiar_numero_inline":true,"m4b_limite_cambio_inline_excedido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_cambiar_numero_inline":true,"m4b_limite_cambio_inline_excedido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_cambiar_numero_inline":false,"m4b_limite_cambio_inline_excedido":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_cambiar_numero_inline":false,"m4b_limite_cambio_inline_excedido":false},"esperado":false}]},{"tipo":"NUEVA","codigo":"M4-B08","clave":"m4b_123","titulo":"Evitar CAPTCHA adicional en paso OTP","descripcion":"Solo si en Paso 2 OTP se intenta presentar un CAPTCHA adicional, BLOQUEAR la doble fricción, sin modificar CAPTCHA del Paso 1 ni controles de otras superficies.","familia":"SECURITY","naturaleza":"CONDUCTA","autoridad":"LEG-SEGURIDAD","dueno":"SEGURIDAD","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","clase":"PANTALLA","condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"m4b_intento_captcha_paso_otp"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"m4b_captcha_adicional_otp_presentado"},"der":{"lit":true}}},"efecto":"BLOQUEAR","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/123","solicitante":"migracion-nucleo"},"pruebas":[{"casuistica":"SE_CUMPLE","entrada":{"m4b_intento_captcha_paso_otp":true,"m4b_captcha_adicional_otp_presentado":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_captcha_paso_otp":true,"m4b_captcha_adicional_otp_presentado":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_captcha_paso_otp":false,"m4b_captcha_adicional_otp_presentado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"m4b_intento_captcha_paso_otp":false,"m4b_captcha_adicional_otp_presentado":false},"esperado":false}]}]'::jsonb) LOOP
  code:=p->>'codigo'; ref_id:=split_part(p->'origen'->>'ref','/',2)::integer;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_familia f JOIN lf_ops.v_reglas_compat_v1 v ON v.id=f.regla_id WHERE f.familia IN ('SECURITY','MFA_OTP_SSO','SESSION','RATE_LIMIT') AND v.id=ref_id)
  THEN RAISE EXCEPTION 'M4B_LEGACY_NOT_FOUND % %',code,ref_id; END IF;
  dry:=lf_ops.nucleo_regla_proponer_v1(p,false);
  IF dry->>'resultado'<>'EVALUADA_SIN_ESCRIBIR' OR (dry->>'bloqueantes')::integer<>0 THEN RAISE EXCEPTION 'M4B_PREFLIGHT % %',code,dry; END IF;
  cases:=0;
  FOR t IN SELECT value FROM jsonb_array_elements(p->'pruebas') LOOP
    truth:=lf_ops.nucleo_eval_v1(p->'condicion',t->'entrada');
    IF truth IS DISTINCT FROM t->'esperado' THEN RAISE EXCEPTION 'M4B_WRONG_CONTROL % case=% expected=% actual=%',code,cases,t->'esperado',truth; END IF;
    cases:=cases+1;
  END LOOP;
  IF cases<>4 THEN RAISE EXCEPTION 'M4B_CASE_COVERAGE %',code; END IF;
  SELECT value INTO bad FROM jsonb_array_elements(p->'pruebas') WITH ORDINALITY x(value,ord) WHERE ord=3;
  IF bad->'esperado' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'M4B_MUTANT_NEGATIVE_CASE_MISSING %',code; END IF;
  -- Remove scope guard (left operand): must activate erroneously on the scope-inactive test.
  mutant_truth:=lf_ops.nucleo_eval_v1(p->'condicion'->'der',bad->'entrada');
  IF mutant_truth IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'M4B_GUARD_MUTANT_SURVIVED % %',code,mutant_truth; END IF;
  RAISE NOTICE 'M4B_CASES % count=% guard_mutant_detected=true',code,cases;
  applied:=lf_ops.nucleo_regla_proponer_v1(p,true);
  IF applied->>'resultado'<>'CANDIDATA' OR applied->>'version'<>'1' THEN RAISE EXCEPTION 'M4B_DOOR_REJECTED % %',code,applied; END IF;
  eval:=lf_ops.nucleo_regla_evaluar_v1(code,true);
  IF eval->>'decision'<>'BLOQUEADA' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(eval->'motivos') m WHERE m->>'dimension'='JUICIO') THEN RAISE EXCEPTION 'M4B_UNJUDGED_MUST_BLOCK % %',code,eval; END IF;
  IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas r JOIN lf_ops.nucleo_regla_versiones v ON v.regla=r.codigo WHERE r.codigo=code AND r.estado='CANDIDATA' AND r.regla_legacy_id IS NULL AND v.version=1 AND v.estado='CANDIDATA' AND v.publicada_desde IS NULL AND v.exigible_desde IS NULL)
  THEN RAISE EXCEPTION 'M4B_NOT_CANDIDATE_ONLY %',code; END IF;
  RAISE NOTICE 'M4B_CANDIDATE %',jsonb_build_object('code',code,'cases',cases,'decision',eval->>'decision','hash',lf_ops.nucleo_hash_paquete_v1(code,1),'estado','CANDIDATA');
  n:=n+1;total_tests:=total_tests+cases;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.lf_error_knowledge WHERE codigo='LF-NUCLEO-M4B-LOGICAL-FACTS-RUNTIME-PENDING-20261123-001') THEN RAISE EXCEPTION 'M4B_EKB_DUPLICATE'; END IF;
 INSERT INTO public.lf_error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,estado,evidencia)
 VALUES('LF-NUCLEO-M4B-LOGICAL-FACTS-RUNTIME-PENDING-20261123-001','NUCLEO_REGLAS','M4B guards de OTP y sesion pendientes de binding','Ocho candidatas M4B tipadas y probadas sintéticamente; sin binding runtime ni juicio independiente, no operan seguridad efectiva.','Migración de textos antes de binding físico con fuente verificable','M4B_LOGICAL_GUARD_BINDING_PENDING','Exigir binding acreditado de Paulo, señal de intento real, tests de integración y juicio independiente antes de publicar.','8 candidatas; 32 casos; 8 mutantes; PG17 BEGIN/ROLLBACK; no publicar','HIGH',1,now(),now(),'M4B-OTP-SESSION-RATE-20261123','ACTIVO','docs/nucleo/LF_M4B_INVENTARIO_112_PRELIMINAR_20261123.md; sandbox/lf_contract_gate_test/nucleo_ci/m4b_8_candidatas_v1.json');
 IF n<>8 OR total_tests<>32 OR (SELECT count(*) FROM public.lf_error_knowledge)<>oldekb+1
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY id) FROM lf_ops.reglas r) IS DISTINCT FROM oldlegacy
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY codigo) FROM lf_ops.nucleo_reglas r WHERE codigo NOT LIKE 'M4-B0%') IS DISTINCT FROM oldrules
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones r WHERE regla NOT LIKE 'M4-B0%') IS DISTINCT FROM oldversions
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones r) IS DISTINCT FROM olddeprec
 OR (SELECT jsonb_agg(to_jsonb(r) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones r WHERE regla NOT LIKE 'M4-B0%') IS DISTINCT FROM oldapps
 OR (SELECT jsonb_agg(jsonb_build_object('nodo',nd.codigo,'r',to_jsonb(e)) ORDER BY nd.codigo,e.regla) FROM lf_ops.nucleo_nodos nd CROSS JOIN LATERAL lf_ops.nucleo_reglas_efectivas_v1(nd.codigo,now()) e) IS DISTINCT FROM oldeffective
 OR (SELECT estado FROM lf_ops.nucleo_reglas WHERE codigo='REG_CHK_007')<>'CANDIDATA'
 THEN RAISE EXCEPTION 'M4B_UNAUTHORIZED_DRIFT count=% tests=%',n,total_tests; END IF;
 RAISE NOTICE 'M4B_PASS 8/8 candidate-only; 32/32 scoped cases; 8 guard mutants; legacy unchanged; zero deprecations';
END $m4$;
COMMIT;
